from functools import lru_cache

from pydantic import field_validator, model_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

DEFAULT_JWT_SECRET = "dev-secret-change-me-please-this-needs-to-be-at-least-32-bytes-long"


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8")

    database_url: str = "sqlite+aiosqlite:///./dev.db"
    jwt_secret: str = DEFAULT_JWT_SECRET
    jwt_access_ttl_minutes: int = 15
    jwt_refresh_ttl_days: int = 30
    environment: str = "development"
    vapid_public_key: str = ""
    vapid_private_key: str = ""
    vapid_claim_email: str = "mailto:admin@example.com"
    cors_allowed_origins: str = "http://localhost:5173"

    @field_validator("jwt_secret", mode="after")
    @classmethod
    def validate_jwt_secret_length(cls, value: str) -> str:
        if len(value.encode("utf-8")) < 32:
            raise ValueError("JWT secret must be at least 32 bytes long")
        return value

    @model_validator(mode="after")
    def validate_jwt_secret_not_default_outside_development(self) -> "Settings":
        # A field_validator on jwt_secret can't see environment (declared after
        # it, and field validators only see earlier fields) - this needs the
        # fully-built model, hence a model_validator instead.
        if self.environment != "development" and self.jwt_secret == DEFAULT_JWT_SECRET:
            raise ValueError(
                "JWT_SECRET must be set to a non-default value when environment != 'development' "
                "- the default is public in source and would let anyone forge tokens"
            )
        return self


@lru_cache
def get_settings() -> Settings:
    return Settings()

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'
import { setTokens } from './tokenStore'

const API_BASE = import.meta.env.VITE_API_BASE_URL as string
const REFRESH_TOKEN_KEY = 'atlas_refresh_token'

export interface AuthUser {
  id: string
  email: string
  role: string
}

interface TokenPair {
  access_token: string
  refresh_token: string
}

interface AuthContextValue {
  user: AuthUser | null
  accessToken: string | null
  isLoading: boolean
  login: (tenantId: string, email: string, password: string) => Promise<void>
  logout: () => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

async function fetchMe(accessToken: string): Promise<AuthUser> {
  const response = await fetch(`${API_BASE}/api/v1/auth/me`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  })
  if (!response.ok) throw new Error('failed to fetch current user')
  return response.json()
}

async function refreshTokens(refreshToken: string): Promise<TokenPair> {
  const response = await fetch(`${API_BASE}/api/v1/auth/refresh`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token: refreshToken }),
  })
  if (!response.ok) throw new Error('refresh failed')
  return response.json()
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null)
  const [accessToken, setAccessToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const storedRefreshToken = localStorage.getItem(REFRESH_TOKEN_KEY)
    if (!storedRefreshToken) {
      setIsLoading(false)
      return
    }
    refreshTokens(storedRefreshToken)
      .then(async (tokens) => {
        const me = await fetchMe(tokens.access_token)
        if (me.role !== 'manager') {
          localStorage.removeItem(REFRESH_TOKEN_KEY)
          setTokens(null, null)
          setIsLoading(false)
          return
        }
        localStorage.setItem(REFRESH_TOKEN_KEY, tokens.refresh_token)
        setTokens(tokens.access_token, tokens.refresh_token)
        setAccessToken(tokens.access_token)
        setUser(me)
        setIsLoading(false)
      })
      .catch(() => {
        localStorage.removeItem(REFRESH_TOKEN_KEY)
        setTokens(null, null)
        setIsLoading(false)
      })
  }, [])

  async function login(tenantId: string, email: string, password: string) {
    const response = await fetch(`${API_BASE}/api/v1/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Tenant-Id': tenantId },
      body: JSON.stringify({ email, password }),
    })
    if (!response.ok) throw new Error('invalid credentials')
    const tokens: TokenPair = await response.json()
    const me = await fetchMe(tokens.access_token)
    if (me.role !== 'manager') {
      throw new Error('this dashboard is for managers')
    }
    localStorage.setItem(REFRESH_TOKEN_KEY, tokens.refresh_token)
    setTokens(tokens.access_token, tokens.refresh_token)
    setAccessToken(tokens.access_token)
    setUser(me)
  }

  function logout() {
    localStorage.removeItem(REFRESH_TOKEN_KEY)
    setTokens(null, null)
    setAccessToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, accessToken, isLoading, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within an AuthProvider')
  return ctx
}

import { useState, type FormEvent } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from './AuthContext'

export function LoginPage() {
  const { login } = useAuth()
  const navigate = useNavigate()
  const [tenantId, setTenantId] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState<string | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  async function handleSubmit(event: FormEvent) {
    event.preventDefault()
    setError(null)
    setIsSubmitting(true)
    try {
      await login(tenantId, email, password)
      navigate('/')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'login failed')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-8">
      <div className="w-full max-w-sm bg-white rounded-lg shadow p-6">
        <h1 className="text-xl font-semibold text-gray-900 mb-6">Manager Dashboard Login</h1>
        <form onSubmit={handleSubmit} className="flex flex-col gap-4">
          <input
            type="text"
            required
            placeholder="Tenant ID (UUID)"
            value={tenantId}
            onChange={(e) => setTenantId(e.target.value)}
            className="border border-gray-300 rounded px-3 py-2 text-sm"
          />
          <input
            type="email"
            required
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="border border-gray-300 rounded px-3 py-2 text-sm"
          />
          <input
            type="password"
            required
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="border border-gray-300 rounded px-3 py-2 text-sm"
          />
          {error && <p className="text-sm text-red-600">{error}</p>}
          <button
            type="submit"
            disabled={isSubmitting}
            className="bg-gray-900 text-white rounded px-3 py-2 text-sm font-medium disabled:opacity-50"
          >
            {isSubmitting ? 'Signing in…' : 'Sign in'}
          </button>
        </form>
      </div>
    </div>
  )
}

import { Navigate } from 'react-router-dom'
import type { ReactNode } from 'react'
import { useAuth } from './AuthContext'

export function ProtectedRoute({ children }: { children: ReactNode }) {
  const { user, isLoading } = useAuth()
  if (isLoading) return <div className="p-8 text-gray-500">Loading…</div>
  if (!user) return <Navigate to="/login" replace />
  return <>{children}</>
}

