import { useEffect, useRef, useState } from 'react'

export function usePolling<T>(fetchFn: () => Promise<T>, intervalMs: number): { data: T | null; error: unknown } {
  const [data, setData] = useState<T | null>(null)
  const [error, setError] = useState<unknown>(null)
  const fetchFnRef = useRef(fetchFn)
  fetchFnRef.current = fetchFn

  useEffect(() => {
    let cancelled = false

    async function tick() {
      try {
        const result = await fetchFnRef.current()
        if (!cancelled) setData(result)
      } catch (err) {
        if (!cancelled) setError(err)
      }
    }

    tick()
    const id = setInterval(tick, intervalMs)
    return () => {
      cancelled = true
      clearInterval(id)
    }
  }, [intervalMs])

  return { data, error }
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renderHook, waitFor } from '@testing-library/react'
import { usePolling } from './usePolling'

describe('usePolling', () => {
  beforeEach(() => vi.useFakeTimers())
  afterEach(() => vi.useRealTimers())

  it('fetches immediately, then again after each interval', async () => {
    const fetchFn = vi.fn().mockResolvedValue(['a'])
    renderHook(() => usePolling(fetchFn, 1000))

    await waitFor(() => expect(fetchFn).toHaveBeenCalledTimes(1))

    vi.advanceTimersByTime(1000)
    await waitFor(() => expect(fetchFn).toHaveBeenCalledTimes(2))

    vi.advanceTimersByTime(1000)
    await waitFor(() => expect(fetchFn).toHaveBeenCalledTimes(3))
  })

  it('stops polling after unmount', async () => {
    const fetchFn = vi.fn().mockResolvedValue(['a'])
    const { unmount } = renderHook(() => usePolling(fetchFn, 1000))

    await waitFor(() => expect(fetchFn).toHaveBeenCalledTimes(1))
    unmount()

    vi.advanceTimersByTime(5000)
    expect(fetchFn).toHaveBeenCalledTimes(1)
  })
})

