import { vi } from 'vitest'

// ponytail: @testing-library/react's `waitFor`/`act` only detect fake timers
// via a global `jest` object (checks `typeof jest !== 'undefined'`), not
// Vitest's `vi.useFakeTimers()`. Without this shim, `waitFor` hangs forever
// under fake timers because its internal microtask-draining `setTimeout(0)`
// is never advanced. See testing-library/dom-testing-library#939.
if (typeof (globalThis as { jest?: unknown }).jest === 'undefined') {
  ;(globalThis as { jest?: { advanceTimersByTime: (ms: number) => void } }).jest = {
    advanceTimersByTime: (ms: number) => vi.advanceTimersByTime(ms),
  }
}

